// psRelease.js - when the problem statements are released (Vibe-A-Thon page: Problem Statement Release + Timeline).
// The dashboard (Site controls -> Problem statements) can change the time without a deploy. If it did, that wins;
// if not, the time written in data/problemStatement.js is used. You do not edit this file.
import { liveValue } from './liveSettings';
import { PS } from '../data/problemStatement';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const STAMP = /^(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d)$/;

// '2026-11-22T00:00' (Indian time) -> { date: '20 Nov 2026', time: '12:00 AM' }
export function istWords(stamp) {
  const m = STAMP.exec(String(stamp || ''));
  if (!m || !MONTHS[Number(m[2]) - 1]) return null;
  const h = Number(m[4]);
  return { date: `${Number(m[3])} ${MONTHS[Number(m[2]) - 1]} ${m[1]}`, time: `${h % 12 || 12}:${m[5]} ${h < 12 ? 'AM' : 'PM'}` };
}

// { ms, label, date, time, custom }   custom = true when the dashboard changed the time
export function psRelease() {
  const v = liveValue('psReleaseAt', null);
  const w = istWords(v);
  const ms = w ? Date.parse(`${v}:00+05:30`) : NaN;
  if (w && Number.isFinite(ms)) return { ms, label: `${w.date}, ${w.time} IST`, date: w.date, time: w.time, custom: true };
  return { ms: Date.parse(PS.releaseAt), label: PS.releaseLabel, date: '', time: '', custom: false };
}
